const contextBlock = [
  'ข้อมูลห้องเรียนวันนี้:',
  `- class_id: ${item.class_id || 'unknown'}`,
  `- avg_mood_score: ${Number.isFinite(avgMood) ? avgMood.toFixed(2) : 'null'} / 5`,
  `- total_responses: ${totalResponses} นักเรียน`,
  `- sentiment_distribution: ${sentimentLine}`,
  '  (very_low / low / okay / good / great)',
  `- dismissal_rate: ${dismissalRate.toFixed(2)}`,
  `- dismissal_pattern_consecutive: ${consecutiveDismissals}`,
  `- inquiry_mode_suggested: ${inquiryModeSuggested}`,
  `- teacher_flag_inquiry_mode: ${metrics.teacher_flag_inquiry_mode === true}`,
  `- inquiry_reason: ${metrics.inquiry_reason || 'none'}`,
  `- recent_recommendation_summary: ${summary.summary_text || summary.reasoning || 'none'}`,
  'กฎการตีความ:',
  '- avg_mood ≤ 2.0 → policy_level = CRITICAL',
  '- avg_mood ≤ 3.0 → policy_level = WARNING',
  '- avg_mood > 3.0 → policy_level = ROUTINE',
