if (Object.prototype.hasOwnProperty.call(item, 'test_force_low_confidence')) {
  contextBlock.push(`- test_force_low_confidence: ${item.test_force_low_confidence === true}`);
}
if (Object.prototype.hasOwnProperty.call(item, 'test_force_invalid_ai_json')) {
  contextBlock.push(`- test_force_invalid_ai_json: ${item.test_force_invalid_ai_json === true}`);
}
if (Object.prototype.hasOwnProperty.call(item, 'test_force_valid_ai_output')) {
  contextBlock.push(`- test_force_valid_ai_output: ${item.test_force_valid_ai_output === true}`);
}
const prompt = [
  'You are the Climate Analysis Agent for a privacy-first classroom climate system.',
  'Use only the aggregated classroom metrics below. Never mention any individual student or invent student-level facts.',
  'Your reasoning and recommendation must be anchored to the actual mood numbers and sentiment distribution.',
  '',
  ...contextBlock,
  '',
  'ข้อกำหนดสำคัญ:',
  '1. reasoning ต้องอ้างอิงสัญญาณจริงของห้อง เช่น avg_mood_score, คะแนนเฉลี่ย, หรือสัดส่วน low/okay/good อย่างชัดเจน',
  '2. recommendation_content ต้องบอกบริบทอารมณ์ของห้องอย่างเฉพาะเจาะจง เช่น นักเรียนส่วนใหญ่อยู่ในช่วง low–okay หรือมี very_low/low เด่น',
  '3. recommendation_content ต้องเสนอเพียง 1 การกระทำที่ครูทำได้ทันทีและผูกกับระดับอารมณ์นั้น',
  '4. recommendation_content ต้องเป็นภาษาไทย, ยาวไม่เกิน 280 ตัวอักษร, ไม่มีชื่อหรือข้อมูลระบุตัวตน',
  '5. ห้ามใช้ถ้อยคำกว้าง ๆ เช่น ตรวจสอบสภาพคล่องของห้องเรียน, สภาพอากาศ, ให้แน่ใจว่าพวกเขาอยู่ในสภาพที่ดี',
  '6. หากสัญญาณอ่อนหรือกำกวม ให้ยังตอบเป็น JSON ที่ถูกต้องได้ แต่ลด confidence_score ให้ต่ำกว่า 0.65 เพื่อให้ workflow fallback เอง',
  '',
  'ตัวอย่างดี (avg_mood = 2.7, low/okay เด่น):',
  'recommendation_content: "นักเรียนส่วนใหญ่รู้สึกกลาง ๆ ถึงต่ำในวันนี้ ลองเปิดพื้นที่ให้แชร์ความรู้สึกก่อนเริ่มคาบ หรือลดปริมาณงานชิ้นแรกลง"',
  '',
  'ตัวอย่างไม่ดี (generic, ห้ามใช้):',
  'recommendation_content: "โปรดตรวจสอบสภาพคล่องของห้องเรียนและสภาพอากาศเพื่อให้แน่ใจว่าพวกเขาอยู่ในสภาพที่ดี"',
  '',
  'ถ้า test_force_low_confidence เป็น true ให้ยังตอบ JSON ที่ถูกต้อง แต่ตั้ง confidence_score ไม่เกิน 0.20',
  'ถ้า test_force_invalid_ai_json เป็น true ให้ตอบ JSON ที่ recommendation_content ว่างเพื่อให้ parser ปฏิเสธ',
  'ถ้า test_force_valid_ai_output เป็น true ให้ตอบ JSON ที่สมบูรณ์และ recommendation_content ต้องไม่ว่าง',
  '',
  'ตอบกลับ ONLY valid JSON ต่อไปนี้ ห้ามมีข้อความอื่น:',
  '{',
  '  "policy_level": "ROUTINE|WARNING|CRITICAL",',
  '  "confidence_score": 0.0,',
  '  "recommendation_content": "Thai <=280 chars, mood-specific, one concrete action",',
  '  "reasoning": "short Thai explanation referencing avg_mood and sentiment",',
  '  "actions_json": null,',
  '  "decision_path": {',
  '    "route": "ai",',
  '    "generated_by": "ollama",',
  '    "steps": []',
  '  },',
  '  "inquiry_mode": false,',
  '  "fallback_used": false',
  '}',
].join('\n');
return {
  json: {
    ...item,
    llm_prompt: prompt,
    llm_provider: 'ollama',
    llm_model: 'qwen2.5:3b',
  },
};

const source = $('Build Ollama Analysis Prompt').first().json || $('Merge Metrics Into Item').first().json || {};
const normalizePolicy = (value) => {
  const text = String(value || '').trim().toUpperCase();
  return ['ROUTINE', 'WARNING', 'CRITICAL'].includes(text) ? text : null;
};
const coerceConfidence = (value) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0;
  return Math.max(0, Math.min(1, numeric));
};
const deriveInquiryMode = (item, fallbackPolicy) => {
  if (typeof item.inquiry_mode === 'boolean') return item.inquiry_mode;
  const metrics = source.teacher_metrics || {};
  if (metrics.inquiry_mode_suggested === true || metrics.teacher_flag_inquiry_mode === true || metrics.is_inquiry_mode === true) return true;
  const dismissalRate = Number(metrics.dismissal_rate ?? source.past_summary?.dismissal_rate ?? 0);
  return dismissalRate > 0.6 && ['WARNING', 'CRITICAL'].includes(fallbackPolicy || '');
};
const defaultDraftForPolicy = (policyLevel) => {
  if (policyLevel === 'CRITICAL') return 'วันนี้มีสัญญาณความรู้สึกต่ำค่อนข้างมาก ลองหยุดเช็กอินสั้น ๆ และลดงานที่กดดันก่อนเริ่มกิจกรรมหลัก';
  if (policyLevel === 'WARNING') return 'นักเรียนส่วนใหญ่ดูอยู่ในช่วงต่ำถึงปานกลาง ลองเริ่มคาบด้วยการเช็กอารมณ์สั้น ๆ และลดงานชิ้นแรกให้เบาลง';
  return 'ภาพรวมอารมณ์ยังพอไปได้ ลองชวนสะท้อนสิ่งที่ทำได้ดี 1 อย่างก่อนเริ่มกิจกรรมถัดไป';
};
const buildRejectedResult = (policyLevel, recommendationContent, reasoning, actions, rejectionReason, fallbackReason = 'generic_content') => ({
  json: {
    ...source,
    policy_level: policyLevel,
    confidence_score: 0,
    recommendation_content: recommendationContent,
    ai_message_draft: recommendationContent,
    reasoning: reasoning || rejectionReason,
    actions_json: actions,
    inquiry_mode: deriveInquiryMode(parsed || {}, policyLevel),
    fallback_used: false,
    ai_attempted: true,
    ai_fallback_reason: fallbackReason,
    decision_path: {
      route: fallbackReason,
      generated_by: 'ollama',
      llm_provider: 'ollama',
      llm_model: 'qwen2.5:3b',
      llm_enabled: true,
      llm_output_rejected: true,
      _rejection_reason: rejectionReason,
    },
  },
});
const rawOutput = typeof $json.text === 'string'
  ? $json.text
  : typeof $json.output === 'string'
    ? $json.output
    : typeof $json.response?.text === 'string'
      ? $json.response.text
      : typeof $json.error === 'string'
        ? ''
        : JSON.stringify($json || {});
if ($json.error) {
  return {
    json: {
      ...source,
      policy_level: null,
      confidence_score: 0,
      recommendation_content: '',
      ai_message_draft: '',
      reasoning: `ollama_error:${String($json.error).slice(0, 160)}`,
      actions_json: {},
      inquiry_mode: false,
      fallback_used: false,
      ai_attempted: true,
      ai_fallback_reason: 'ollama_error',
      decision_path: {
        route: 'ollama_error',
        generated_by: 'ollama',
        llm_provider: 'ollama',
        llm_model: 'qwen2.5:3b',
        llm_enabled: true,
        llm_output_rejected: true,
        _rejection_reason: 'ollama_error',
      },
    },
  };
}
let parsed;
try {
  const cleaned = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = null;
}
if (source.test_force_invalid_ai_json === true) {
  parsed = { ...(parsed || {}), recommendation_content: '', reasoning: 'forced_invalid_json_for_manual_test' };
}
const policyLevel = normalizePolicy(parsed?.policy_level);
let confidenceScore = coerceConfidence(parsed?.confidence_score);
if (source.test_force_low_confidence === true) confidenceScore = 0.2;
let recommendationContent = typeof parsed?.recommendation_content === 'string' ? parsed.recommendation_content.replace(/\s+/g, ' ').trim() : '';
const reasoning = typeof parsed?.reasoning === 'string' ? parsed.reasoning.replace(/\s+/g, ' ').trim().slice(0, 500) : '';
const actions = parsed?.actions_json == null
  ? null
  : typeof parsed.actions_json === 'object' && !Array.isArray(parsed.actions_json)
    ? parsed.actions_json
    : Array.isArray(parsed.actions_json)
      ? parsed.actions_json
      : {};
if (!recommendationContent && source.test_force_valid_ai_output === true && policyLevel) {
  recommendationContent = defaultDraftForPolicy(policyLevel);
  confidenceScore = Math.max(confidenceScore, 0.72);
}
const genericPhrases = [
  'ตรวจสอบสภาพคล่อง',
  'สภาพอากาศ',
  'ให้แน่ใจว่าพวกเขาอยู่ในสภาพที่ดี',
  'ensure they are in good condition',
];
const moodAnchors = ['avg_mood', 'คะแนน', 'อารมณ์', 'บรรยากาศ', 'ต่ำ', 'ปานกลาง', 'low', 'okay'];
const contentLower = recommendationContent.toLowerCase();
const reasoningLower = reasoning.toLowerCase();
const isGeneric = genericPhrases.some((phrase) => recommendationContent.includes(phrase) || contentLower.includes(String(phrase).toLowerCase()));
const isTooShort = recommendationContent.length < 20;
const hasMoodAnchor = moodAnchors.some((anchor) => reasoning.includes(anchor) || reasoningLower.includes(String(anchor).toLowerCase()));
const valid = Boolean(policyLevel && recommendationContent && reasoning);
if (!valid) {
  return buildRejectedResult(policyLevel, recommendationContent, reasoning || 'ollama_output_invalid', actions, parsed ? 'ollama_output_invalid' : 'ollama_parse_failed', parsed ? 'ollama_output_invalid' : 'ollama_parse_failed');
}
if (isGeneric || isTooShort || !hasMoodAnchor) {
  return buildRejectedResult(policyLevel, recommendationContent, reasoning || 'generic_content', actions, 'generic_content');
}
const decisionPath = parsed?.decision_path && typeof parsed.decision_path === 'object' && !Array.isArray(parsed.decision_path)
  ? parsed.decision_path
  : {};
return {
  json: {
    ...source,
    policy_level: policyLevel,
    confidence_score: confidenceScore,
    recommendation_content: recommendationContent,
    ai_message_draft: recommendationContent,
    reasoning,
    actions_json: actions,
    inquiry_mode: deriveInquiryMode(parsed, policyLevel),
    fallback_used: false,
    ai_attempted: true,
    ai_fallback_reason: null,
    decision_path: {
      ...decisionPath,
      route: decisionPath.route || 'ai',
      generated_by: 'ollama',
      llm_provider: 'ollama',
      llm_model: 'qwen2.5:3b',
      llm_enabled: true,
      llm_output_rejected: false,
    },
  },
};

const metrics = $json.teacher_metrics || {};
const summary = $json.past_summary || {};
const avgMood = Number($json.avg_mood_score ?? metrics.avg_mood_score ?? 3.5);
const dismissalRate = Number(metrics.dismissal_rate ?? summary.dismissal_rate ?? 0);
const consecutiveDismissals = Number(metrics.dismissal_pattern_consecutive ?? 0);
const teacherFlagInquiryMode = metrics.teacher_flag_inquiry_mode === true || metrics.is_inquiry_mode === true;
const inquiryReason = metrics.inquiry_reason || (teacherFlagInquiryMode ? 'teacher_flag' : dismissalRate > 0.6 && consecutiveDismissals >= 2 ? 'dismissal_pattern' : null);
const aiFallbackReason = $json.ai_fallback_reason || null;
const aiAttempted = $json.ai_attempted === true;

let policyLevel = 'ROUTINE';
let priority = 'low';

if (avgMood <= 2.0) {
  policyLevel = 'CRITICAL';
  priority = 'high';
} else if (avgMood <= 3.0) {
  policyLevel = 'WARNING';
  priority = 'medium';
}

const inquiryMode = teacherFlagInquiryMode || (
  dismissalRate > 0.6 &&
  consecutiveDismissals >= 2 &&
  ['WARNING', 'CRITICAL'].includes(policyLevel)
);

let templateKey = policyLevel.toLowerCase();
let recommendationContent = 'วันนี้บรรยากาศห้องเรียนอยู่ในเกณฑ์ปกติ ลองชวนเด็กสะท้อนสิ่งที่ทำได้ดีสัก 1 อย่างในคาบนี้';

if (policyLevel === 'WARNING') {
  templateKey = inquiryMode ? 'warning_inquiry_th' : 'warning_standard_th';
  recommendationContent = inquiryMode
    ? 'บรรยากาศเริ่มต่ำลง คุณครูคิดว่าอะไรอาจเป็นสาเหตุ และอยากให้ระบบเสนอการช่วยเหลือแบบไหนบ้าง?'
    : 'บรรยากาศเริ่มต่ำกว่าปกติ ลองถามนักเรียนว่าอะไรทำให้ไม่ค่อยมีส่วนร่วม และจะลองปรับอะไรในคาบต่อไป';
}

if (policyLevel === 'CRITICAL') {
  templateKey = inquiryMode ? 'critical_inquiry_th' : 'critical_standard_th';
  recommendationContent = inquiryMode
    ? 'ระบบเห็นสัญญาณที่น่ากังวล คุณครูมองว่าสถานการณ์ห้องตอนนี้เป็นอย่างไร และอยากให้ระบบช่วยแบบไหนมากกว่ากัน?'
    : 'ระบบเห็นสัญญาณน่ากังวลต่อเนื่อง ลองเปิดพื้นที่พูดคุยสั้น ๆ ให้เด็กเล่าเรื่องที่กังวล แล้ววางแผนช่วยเหลือร่วมกัน';
}

const rulesFired = [];
if (avgMood <= 3.0) rulesFired.push('avg_mood_low');
if (avgMood <= 2.0) rulesFired.push('avg_mood_critical');
if (dismissalRate > 0.6) rulesFired.push('high_dismissal');
if (teacherFlagInquiryMode) rulesFired.push('teacher_flag_inquiry_mode');
if (inquiryMode && !teacherFlagInquiryMode) rulesFired.push('dismissal_pattern_inquiry_mode');
if (aiAttempted) rulesFired.push('ollama_fallback');
if (aiFallbackReason) rulesFired.push(`fallback_reason:${aiFallbackReason}`);

const reasoning = [
  'rule_core',
  'avg_mood_score=' + avgMood.toFixed(2),
  'dismissal_rate=' + dismissalRate.toFixed(2),
  'dismissal_pattern_consecutive=' + consecutiveDismissals,
  'policy_level=' + policyLevel,
  'inquiry_mode=' + inquiryMode,
  aiFallbackReason ? 'fallback_reason=' + aiFallbackReason : null,
].filter(Boolean).join(' | ');

const decisionPath = {
  generated_by: 'fallback',
  route: aiFallbackReason ? 'fallback_after_ollama' : 'rules_only',
  policy_level: policyLevel,
  mode: inquiryMode ? 'inquiry' : policyLevel.toLowerCase(),
  inquiry_mode: inquiryMode,
  llm_enabled: aiAttempted,
  llm_provider: aiAttempted ? 'ollama' : null,
  llm_model: aiAttempted ? 'qwen2.5:3b' : null,
  fallback_reason: aiFallbackReason,
  template_key: templateKey,
  rules_fired: rulesFired,
  thresholds: {
    avg_mood_score: avgMood,
    dismissal_rate: dismissalRate,
    dismissal_pattern_consecutive: consecutiveDismissals,
  },
  teacher_flag_inquiry_mode: teacherFlagInquiryMode,
  inquiry_reason: inquiryReason,
  priority,
};

return {
  json: {
    ...$json,
    policy_level: policyLevel,
    priority,
    confidence_score: inquiryMode ? 0.78 : 0.75,
    recommendation_content: recommendationContent,
    ai_message_draft: recommendationContent,
    reasoning,
    actions_json: {
      recommended_action: inquiryMode ? 'reflective_prompt' : 'teacher_follow_up',
      priority,
    },
    decision_path: decisionPath,
    inquiry_mode: inquiryMode,
    fallback_used: true,
  },
};

const item = { ...$json };
item.ai_attempted = true;
item.ai_fallback_reason = item.ai_fallback_reason || 'low_ai_confidence';
item.decision_path = {
  ...(item.decision_path || {}),
  route: item.ai_fallback_reason,
  generated_by: 'ollama',
  llm_provider: 'ollama',
  llm_model: 'qwen2.5:3b',
  llm_enabled: true,
  llm_output_rejected: item.ai_fallback_reason !== 'low_ai_confidence',
